#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char s[64];
    if (scanf("%63s", s) != 1) return 0;
    int n = (int)strlen(s);

    /* Antigo padrão Brasileiro: LLL-DDDD (8 caracteres) */
    int br = (n == 8 &&
              isupper((unsigned char)s[0]) && isupper((unsigned char)s[1]) &&
              isupper((unsigned char)s[2]) && s[3] == '-' &&
              isdigit((unsigned char)s[4]) && isdigit((unsigned char)s[5]) &&
              isdigit((unsigned char)s[6]) && isdigit((unsigned char)s[7]));

    /* Novo padrão Mercosul: LLLDLLDD (7 caracteres) */
    int ms = (n == 7 &&
              isupper((unsigned char)s[0]) && isupper((unsigned char)s[1]) &&
              isupper((unsigned char)s[2]) && isdigit((unsigned char)s[3]) &&
              isupper((unsigned char)s[4]) && isdigit((unsigned char)s[5]) &&
              isdigit((unsigned char)s[6]));

    if (br) printf("1\n");
    else if (ms) printf("2\n");
    else printf("0\n");

    return 0;
}
